import { useEffect, useState } from 'react'
import useSWR from 'swr'
import api from '@/lib/api'
import { useAuthStore } from '@/stores/auth.store'

type Project = { id: string; name: string; total_budget?: string }
type Instrument = { id: string; project_id: string; number: string; kind?: string; grantor_sphere?: string; grantor?: string; work_plan_document_id?: string; configuration?: Record<string, unknown> }
type Requirement = { id: string; status: string; applies: boolean; evidence_ids: string[]; rule: { title: string; origin: string; source_reference?: string; blocks_close: boolean } }
type Document = { id: string; kind: string; format: string; version: number; sha256: string; signature_state: string; signed_document_id?: string }
type Month = { id: string; month: string; revision: number; status: string; execution_data?: Execution; requirements: Requirement[]; documents: Document[]; point_entries: { id: string; team_link_id: string; start_at: string; end_at?: string; kind: string }[]; events: { id: string; action: string; reason?: string; created_at: string }[] }
type Execution = { activities: string; results: string; deviations: string; justifications: string; source_ids: string[] }
type Team = { id: string; name: string; role: string; weekly_minutes?: number }
type Attendance = { id: string; nome: string; modalidade?: string; aulas: { id: string; inicio: string; status: string }[]; beneficiarios: { matricula_id: string; nome: string; percent: number | null; pending: number; records: { aula_id: string; status: string }[] }[] }
type Financial = { entries: { id: string; date: string; description: string; status: string; type: string; amount: string }[]; approved_unpaid: string; received: string; spent: string; period_balance: string; reconciliation_message: string }
type Overview = { month: Month; attendance: Attendance[]; attendance_summary: { enrollments: number; presences: number; unique_participants: number }; team: Team[]; financial: Financial; blockers: Requirement[]; attendance_pending: number; point: { minutes: number; issues: string[] }; source_changed: boolean; validations: { id: string; stage: string; status: string; role: string; comment?: string; created_at: string }[]; indicatorResults: { indicator: { id: string; name: string; unit?: string; target?: string }; results: { id: string; expected: string; actual?: string; method: string; source?: string; scope: string }[] }[] }
type Expense = { transaction: { id: string; description: string; amount: string; status: string; date: string; category?: string }; control: null | { id: string; budget_line?: string; account_reference?: string; work_plan_version?: string; scope?: string; funding_source: string; classification: string; release_status: string; documents: Record<string, { status: string; evidence_id?: string; justification?: string }>; payments: { id: string; amount: string; statement_id?: string; occurrence: boolean }[] } }
type Official = { id: string; title: string; period: string; status: string; due_at?: string; legal_basis?: string; protocol_number?: string }
type Media = { id: string; kind: string; recorded_on: string; location: string; scope: string; description: string; public_release: boolean }
const fetcher = (url: string) => api.get(url).then(r => r.data)
const money = (value: string) => Number(value).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })
const human = (value: string) => value.replaceAll('_', ' ').toLowerCase().replace(/^./, x => x.toUpperCase())
const tabs = ['Visão geral', 'Financeiro', 'Execução física', 'Resultados', 'Documentos', 'Prestação oficial'] as const
type Tab = typeof tabs[number]
function Card({ title, children }: { title: string; children: React.ReactNode }) { return <section className="rounded-xl border bg-white p-5 space-y-3"><h3 className="font-semibold text-gray-900">{title}</h3>{children}</section> }

export default function MonthlyWorkspace({ projectId: fixedProjectId }: { projectId?: string } = {}) {
  const currentUser = useAuthStore(s => s.user)
  const { data: projectResult } = useSWR<{ data: Project[] }>(fixedProjectId ? null : '/projects?limit=100', fetcher)
  const { data: fixedProject } = useSWR<Project>(fixedProjectId ? `/projects/${fixedProjectId}` : null, fetcher)
  const [projectId, setProjectId] = useState(fixedProjectId ?? '')
  const { data: instruments, mutate: reloadInstruments } = useSWR<Instrument[]>(projectId ? `/accountability/monthly/instruments?project_id=${projectId}` : null, fetcher)
  const [instrumentId, setInstrumentId] = useState('')
  const instrument = instruments?.find(i => i.id === instrumentId)
  const { data: expenses, mutate: reloadExpenses } = useSWR<Expense[]>(instrumentId ? `/accountability/monthly/instruments/${instrumentId}/expenses` : null, fetcher)
  const { data: official, mutate: reloadOfficial } = useSWR<Official[]>(instrumentId ? `/accountability/monthly/instruments/${instrumentId}/official` : null, fetcher)
  const { data: media, mutate: reloadMedia } = useSWR<Media[]>(instrumentId ? `/accountability/monthly/instruments/${instrumentId}/media` : null, fetcher)
  const [month, setMonth] = useState(new Date().toISOString().slice(0, 7))
  const { data: months, mutate: reloadMonths } = useSWR<Month[]>(instrumentId ? `/accountability/monthly?instrument_id=${instrumentId}` : null, fetcher)
  const [selectedId, setSelectedId] = useState('')
  const { data: view, error, isLoading, mutate } = useSWR<Overview>(selectedId ? `/accountability/monthly/${selectedId}` : null, fetcher)
  const [tab, setTab] = useState<Tab>('Visão geral')
  const [busy, setBusy] = useState(false), [message, setMessage] = useState('')
  const [newNumber, setNewNumber] = useState(''), [newKind, setNewKind] = useState(''), [newSphere, setNewSphere] = useState('')
  const [instrumentKind, setInstrumentKind] = useState('A confirmar'), [grantor, setGrantor] = useState(''), [signedId, setSignedId] = useState(''), [planId, setPlanId] = useState('')
  const [approvedLines, setApprovedLines] = useState(''), [approvedPlan, setApprovedPlan] = useState(''), [specificAccount, setSpecificAccount] = useState(''), [dueDay, setDueDay] = useState('9')
  const [lineLimits, setLineLimits] = useState('')
  const [validFrom, setValidFrom] = useState(''), [validUntil, setValidUntil] = useState(''), [agreedAmount, setAgreedAmount] = useState(''), [officialUrl, setOfficialUrl] = useState(''), [retentionYears, setRetentionYears] = useState('')
  const [versionNumber, setVersionNumber] = useState(''), [versionStatus, setVersionStatus] = useState('EM_ANALISE'), [versionDocument, setVersionDocument] = useState(''), [versionEffective, setVersionEffective] = useState('')
  const [budgetLine, setBudgetLine] = useState(''), [account, setAccount] = useState(''), [planVersion, setPlanVersion] = useState('')
  const [expenseClass, setExpenseClass] = useState('REVISAO'), [classBasis, setClassBasis] = useState('')
  const [fundingSource, setFundingSource] = useState('PARCERIA')
  const [paymentAmount, setPaymentAmount] = useState(''), [paymentDate, setPaymentDate] = useState(''), [paymentReference, setPaymentReference] = useState(''), [paymentEvidence, setPaymentEvidence] = useState('')
  const [officialTitle, setOfficialTitle] = useState('Prestação anual'), [officialPeriod, setOfficialPeriod] = useState(''), [protocolEvidence, setProtocolEvidence] = useState('')
  const [officialDue, setOfficialDue] = useState(''), [officialBasis, setOfficialBasis] = useState(''), [officialResponsible, setOfficialResponsible] = useState(''), [officialDocs, setOfficialDocs] = useState('')
  const [expenseStatus, setExpenseStatus] = useState('TODOS'), [expenseScope, setExpenseScope] = useState('TODOS')
  const [indicatorId, setIndicatorId] = useState(''), [expected, setExpected] = useState(''), [actual, setActual] = useState(''), [method, setMethod] = useState(''), [resultSource, setResultSource] = useState('')
  const [mediaId, setMediaId] = useState(''), [mediaKind, setMediaKind] = useState('FOTO'), [mediaDate, setMediaDate] = useState(''), [mediaPlace, setMediaPlace] = useState(''), [mediaScope, setMediaScope] = useState(''), [mediaDescription, setMediaDescription] = useState('')
  const [mediaLesson, setMediaLesson] = useState('')
  const [executionScope, setExecutionScope] = useState('TODAS')
  useEffect(() => {
    if (!instrument) return
    setInstrumentKind(instrument.kind || 'A confirmar')
    setGrantor(instrument.grantor || '')
    setSignedId(String(instrument.configuration?.signed_document_id || ''))
    setPlanId(instrument.work_plan_document_id || '')
    setApprovedLines(Array.isArray(instrument.configuration?.approved_budget_lines) ? (instrument.configuration.approved_budget_lines as string[]).join(', ') : '')
    setLineLimits(Object.entries((instrument.configuration?.budget_line_limits || {}) as Record<string, number>).map(([k, v]) => `${k}=${v}`).join('; '))
    setApprovedPlan(String(instrument.configuration?.approved_plan_version || ''))
    setSpecificAccount(String(instrument.configuration?.account_reference || ''))
    setDueDay(String(instrument.configuration?.internal_due_day || 9))
    setValidFrom(String(instrument.configuration?.valid_from || ''))
    setValidUntil(String(instrument.configuration?.valid_until || ''))
    setAgreedAmount(String(instrument.configuration?.agreed_amount || (instrument.number === '994898' ? '294000.00' : '')))
    setOfficialUrl(String(instrument.configuration?.official_url || ''))
    setRetentionYears(String(instrument.configuration?.retention_years || ''))
  }, [instrument?.id])
  const [teamName, setTeamName] = useState(''), [teamRole, setTeamRole] = useState('')
  const [ruleId, setRuleId] = useState(''), [ruleSource, setRuleSource] = useState(''), [ruleBlocks, setRuleBlocks] = useState(false)
  const [evidenceRule, setEvidenceRule] = useState(''), [evidenceDoc, setEvidenceDoc] = useState('')
  const [protocolNumber, setProtocolNumber] = useState(''), [protocolPortal, setProtocolPortal] = useState(''), [protocolDate, setProtocolDate] = useState('')
  const [execution, setExecution] = useState<Execution>({ activities: '', results: '', deviations: '', justifications: '', source_ids: [] })
  useEffect(() => { setExecution({ activities: view?.month.execution_data?.activities ?? '', results: view?.month.execution_data?.results ?? '',
    deviations: view?.month.execution_data?.deviations ?? '', justifications: view?.month.execution_data?.justifications ?? '',
    source_ids: view?.month.execution_data?.source_ids ?? [] }) }, [view?.month.id, view?.month.execution_data])
  const [teamFrom, setTeamFrom] = useState(''), [pointTeam, setPointTeam] = useState(''), [pointStart, setPointStart] = useState(''), [pointEnd, setPointEnd] = useState('')

  async function action(fn: () => Promise<unknown>, success: string) {
    setBusy(true); setMessage('')
    try { await fn(); await Promise.all([mutate(), reloadMonths(), reloadExpenses(), reloadOfficial(), reloadMedia(), reloadInstruments()]); setMessage(success) }
    catch (e) { const data = (e as { response?: { data?: { message?: string | string[] } } }).response?.data?.message; setMessage(Array.isArray(data) ? data.join('; ') : data ?? 'Não foi possível concluir. Confira os dados e tente novamente.') }
    finally { setBusy(false) }
  }
  async function download(url: string, filename: string) {
    try { const { data } = await api.get(url, { responseType: 'blob' }); const object = URL.createObjectURL(data); const link = document.createElement('a'); link.href = object; link.download = filename; link.click(); setTimeout(() => URL.revokeObjectURL(object), 1000) }
    catch { setMessage('Não foi possível baixar o arquivo.') }
  }
  async function open() {
    if (!instrumentId) return
    await action(async () => { const { data } = await api.post('/accountability/monthly', { instrument_id: instrumentId, month }); setSelectedId(data.id) }, 'Competência aberta com as configurações vigentes. Confira os dados deste mês.')
  }
  async function generate(kind: string, format: string, team_id?: string, turma_id?: string) {
    if (!view) return
    await action(() => api.post(`/accountability/monthly/${view.month.id}/documents`, { kind, format, team_id, turma_id }), 'Documento gerado como rascunho. Confira, assine e anexe a versão assinada quando aplicável.')
  }
  async function editExpenseDocument(transactionId: string, control: NonNullable<Expense['control']>, kind: string) {
    const previous = control.documents?.[kind]
    const status = window.prompt(`${human(kind)}: PENDENTE, ANEXADO, VALIDADO ou NAO_SE_APLICA`, previous?.status || 'PENDENTE')?.toUpperCase()
    if (!status) return
    const evidence_id = status === 'ANEXADO' || status === 'VALIDADO' ? window.prompt('ID do documento cadastrado no projeto:', previous?.evidence_id || '') || '' : ''
    const justification = status === 'NAO_SE_APLICA' ? window.prompt('Justificativa da dispensa:', previous?.justification || '') || '' : ''
    await action(() => api.patch(`/accountability/monthly/instruments/${instrumentId}/expenses/${transactionId}`, {
      documents: { ...control.documents, [kind]: { status, evidence_id, justification } },
    }), 'Checklist da despesa atualizado.')
  }
  const active = view?.month.status === 'ABERTA'
  const closingStatus = view?.month.status === 'FECHADA' ? 'Aprovado internamente' : view?.validations?.length ? 'Em revisão' : 'Em preparação'
  const internalDueDate = view ? new Date(Date.UTC(Number(view.month.month.slice(0, 4)), Number(view.month.month.slice(5, 7)), Number(instrument?.configuration?.internal_due_day || 9), 12)).toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo' }) : ''
  const filteredExpenses = expenses?.filter(({ transaction: t, control: c }) => t.date.slice(0, 7) === month && (expenseStatus === 'TODOS' || (c?.release_status || 'PREPARACAO') === expenseStatus) && (expenseScope === 'TODOS' || (c?.scope || 'GERAL') === expenseScope))
  const filteredAttendance = view?.attendance.filter(t => executionScope === 'TODAS' || t.modalidade === executionScope)
  const paidMonth = filteredExpenses?.reduce((sum, x) => sum + (x.control?.payments.reduce((n, p) => n + Number(p.amount), 0) || 0), 0) || 0
  const reconciledMonth = filteredExpenses?.reduce((sum, x) => sum + (x.control?.payments.filter(p => p.statement_id).reduce((n, p) => n + Number(p.amount), 0) || 0), 0) || 0
  const objectClassified = expenses?.filter(x => x.control?.funding_source === 'PARCERIA' && x.control?.classification === 'OBJETO' && x.control?.release_status === 'LIBERADA').reduce((n, x) => n + Number(x.transaction.amount), 0) || 0
  const limitedClassified = expenses?.filter(x => x.control?.funding_source === 'PARCERIA' && x.control?.classification === 'LIMITE_25' && x.control?.release_status === 'LIBERADA').reduce((n, x) => n + Number(x.transaction.amount), 0) || 0
  const missing = view ? [
    ...view.blockers.map(r => ({ title: r.rule.title, why: 'Requisito confirmado que bloqueia o fechamento', tab: 'Documentos' as Tab })),
    ...(view.attendance_pending ? [{ title: `${view.attendance_pending} chamadas sem conferência`, why: 'Sem registro não significa falta', tab: 'Execução física' as Tab }] : []),
    ...view.point.issues.map(x => ({ title: x, why: 'Confira os intervalos lançados', tab: 'Execução física' as Tab })),
  ] : []

  return <div className="space-y-5">
    <Card title="Preparação mensal do dossiê">
      <p className="text-sm text-gray-600">Selecione projeto, instrumento e competência. O checklist é configurável e não comprova, por si só, conformidade com o instrumento.</p>
      <div className="grid gap-3 md:grid-cols-3">
        {!fixedProjectId && <label className="text-sm">Projeto<select className="input mt-1" value={projectId} onChange={e => { setProjectId(e.target.value); setInstrumentId(''); setSelectedId('') }}><option value="">Selecione</option>{projectResult?.data?.map(p => <option value={p.id} key={p.id}>{p.name}</option>)}</select></label>}
        <label className="text-sm">Instrumento<select className="input mt-1" value={instrumentId} onChange={e => { setInstrumentId(e.target.value); setSelectedId('') }}><option value="">Selecione</option>{instruments?.map(i => <option value={i.id} key={i.id}>{i.number}</option>)}</select></label>
        <label className="text-sm">Mês e ano<input type="month" className="input mt-1" value={month} onChange={e => setMonth(e.target.value)} /></label>
      </div>
      {projectId && <div className="grid gap-2 md:grid-cols-4"><input className="input" placeholder="Número do instrumento" value={newNumber} onChange={e => setNewNumber(e.target.value)} /><select className="input" value={newKind} onChange={e => setNewKind(e.target.value)}><option value="">A confirmar</option>{['Termo de Fomento', 'Termo de Colaboração', 'Convênio', 'Outro'].map(k => <option key={k}>{k}</option>)}</select><input className="input" placeholder="Órgão concedente" value={newSphere} onChange={e => setNewSphere(e.target.value)} /><button disabled={busy || !(newNumber || fixedProject?.name?.toLowerCase().includes('movimento cidadão'))} className="btn-secondary" onClick={() => action(async () => { const { data } = await api.post('/accountability/monthly/instruments', { project_id: projectId, number: newNumber || '994898', kind: newKind || undefined, grantor: newSphere || undefined }); setInstrumentId(data.id); await reloadInstruments() }, 'Instrumento vinculado. Confira os dados registrados e confirme a configuração.')}>Vincular instrumento{fixedProject?.name?.toLowerCase().includes('movimento cidadão') ? ' 994898' : ''}</button></div>}
      <div className="flex flex-wrap gap-2"><button disabled={busy || !instrumentId || !month} onClick={open} className="btn-primary">Abrir competência</button>{months?.map(m => <button key={m.id} className={`btn-secondary text-xs ${selectedId === m.id ? 'ring-2 ring-brand-500' : ''}`} onClick={() => setSelectedId(m.id)}>{m.month.slice(0, 7)} · v{m.revision} · {human(m.status)}</button>)}</div>
    </Card>
    {instrument && <Card title={`Instrumento ${instrument.number} · ${instrument.kind || 'A confirmar'}`}>
      <p className="text-sm text-gray-600">{instrument.grantor || 'Órgão concedente a confirmar'} · Prazo oficial a confirmar. Entrega interna: dia {String(instrument.configuration?.internal_due_day || 9)} do mês seguinte, horário de Brasília.</p>
      {instrument.number === '994898' && <div className="rounded-lg bg-amber-50 p-3 text-sm text-amber-900"><strong>Simulação sobre R$ 294.000,00</strong><p>Execução do objeto: mínimo 75% = R$ 220.500,00. Limite de 25% = até R$ 73.500,00.</p><p>Classificado e liberado na parceria, acumulado: objeto {money(String(objectClassified))}; limite de 25% {money(String(limitedClassified))}. Despesas em revisão não entram.</p><p>Portaria MESP nº 16/2026: aplicação ao instrumento em conferência.</p>{fixedProject?.total_budget && Number(fixedProject.total_budget) !== 294000 && <p>Conferir divergência: valor registrado no projeto {money(fixedProject.total_budget)}.</p>}</div>}
      <div className="grid gap-2 md:grid-cols-4"><select className="input" value={instrumentKind} onChange={e => setInstrumentKind(e.target.value)}>{['A confirmar', 'Termo de Fomento', 'Termo de Colaboração', 'Convênio', 'Outro'].map(k => <option key={k}>{k}</option>)}</select><input className="input" placeholder="Órgão concedente" value={grantor} onChange={e => setGrantor(e.target.value)} /><input className="input" placeholder="ID do termo assinado" value={signedId} onChange={e => setSignedId(e.target.value)} /><input className="input" placeholder="ID do Plano de Trabalho aprovado" value={planId} onChange={e => setPlanId(e.target.value)} /></div>
      <div className="grid gap-2 md:grid-cols-5"><input className="input" placeholder="Rubricas aprovadas, separadas por vírgula" value={approvedLines} onChange={e => setApprovedLines(e.target.value)} /><input className="input" placeholder="Saldos: Rubrica=Valor; ..." value={lineLimits} onChange={e => setLineLimits(e.target.value)} /><input className="input" placeholder="Versão aprovada do plano" value={approvedPlan} onChange={e => setApprovedPlan(e.target.value)} /><input className="input" placeholder="Conta específica" value={specificAccount} onChange={e => setSpecificAccount(e.target.value)} /><input className="input" type="number" min="1" max="28" aria-label="Dia do prazo interno" value={dueDay} onChange={e => setDueDay(e.target.value)} /></div>
      <div className="grid gap-2 md:grid-cols-5"><input className="input" type="date" aria-label="Início da vigência" value={validFrom} onChange={e => setValidFrom(e.target.value)} /><input className="input" type="date" aria-label="Fim da vigência" value={validUntil} onChange={e => setValidUntil(e.target.value)} /><input className="input" placeholder="Valor pactuado (R$)" value={agreedAmount} onChange={e => setAgreedAmount(e.target.value)} /><input className="input" placeholder="Link oficial HTTPS" value={officialUrl} onChange={e => setOfficialUrl(e.target.value)} /><input className="input" type="number" min="1" placeholder="Guarda (anos)" aria-label="Guarda documental em anos" value={retentionYears} onChange={e => setRetentionYears(e.target.value)} /></div>
      <button className="btn-secondary" disabled={busy} onClick={() => action(() => api.patch(`/accountability/monthly/instruments/${instrumentId}`, { kind: instrumentKind, grantor, ...(signedId && { signed_document_id: signedId }), ...(planId && { work_plan_document_id: planId }), ...(approvedLines && { approved_budget_lines: approvedLines.split(',').map(x => x.trim()).filter(Boolean) }), ...(lineLimits && { budget_line_limits: Object.fromEntries(lineLimits.split(';').map(x => x.trim().split('=').map(y => y.trim())).filter(x => x.length === 2).map(([key, value]) => [key, Number(value.replace(',', '.'))])) }), ...(approvedPlan && { approved_plan_version: approvedPlan }), ...(specificAccount && { account_reference: specificAccount }), ...(validFrom && { valid_from: validFrom }), ...(validUntil && { valid_until: validUntil }), ...(agreedAmount && { agreed_amount: agreedAmount.replace(',', '.') }), ...(officialUrl && { official_url: officialUrl }), ...(retentionYears && { retention_years: Number(retentionYears) }), internal_due_day: Number(dueDay) || 9 }), 'Configuração salva. Confira vigência, conta e responsáveis no termo assinado.')}>Salvar configuração</button>
      <div className="border-t pt-3"><h4 className="font-medium text-sm">Versões e aditivos do Plano de Trabalho</h4>{Array.isArray(instrument.configuration?.plan_versions) && (instrument.configuration.plan_versions as { version: string; status: string; effective_from?: string }[]).map((v, index) => <p key={index} className="text-sm">Versão {v.version} · {human(v.status)} · {v.effective_from || 'efeito a confirmar'}</p>)}<div className="grid gap-2 md:grid-cols-5 mt-2"><input className="input" placeholder="Número da versão" value={versionNumber} onChange={e => setVersionNumber(e.target.value)} /><select className="input" value={versionStatus} onChange={e => setVersionStatus(e.target.value)}><option value="EM_ANALISE">Em análise</option><option value="APROVADO">Aprovado</option><option value="REJEITADO">Rejeitado</option></select><input className="input" placeholder="ID do documento" value={versionDocument} onChange={e => setVersionDocument(e.target.value)} /><input className="input" type="date" value={versionEffective} onChange={e => setVersionEffective(e.target.value)} /><button className="btn-secondary" disabled={busy || !versionNumber || !versionDocument} onClick={() => action(() => api.post(`/accountability/monthly/instruments/${instrumentId}/plan-versions`, { version: versionNumber, status: versionStatus, document_id: versionDocument, ...(versionEffective && { effective_from: versionEffective }) }), 'Versão registrada. As alterações em análise ficam separadas do plano aprovado.')}>Registrar versão</button></div></div>
    </Card>}
    {message && <p role="status" className="rounded-lg border bg-white p-3 text-sm">{message}</p>}
    {error && <p role="alert" className="text-red-700">Falha ao carregar a competência. Atualize os dados e tente novamente.</p>}
    {isLoading && <p>Carregando competência...</p>}
    {view && <>
      <div className="grid gap-3 md:grid-cols-4">{[
        ['Documentos', String(view.month.documents.length)], ['Pendências críticas', String(missing.length)],
        ['Execução', `${view.attendance.reduce((n, x) => n + x.aulas.length, 0)} aulas registradas`], ['Fechamento', `${closingStatus} · revisão ${view.month.revision}`],
      ].map(([title, value]) => <div key={title} className="rounded-xl border bg-white p-4"><p className="text-xs text-gray-500">{title}</p><strong className="text-lg">{value}</strong></div>)}</div>
      <Card title="Prazos e situação"><p className="text-sm">Instrumento {instrument?.number || 'não selecionado'} · competência {view.month.month.slice(5, 7)}/{view.month.month.slice(0, 4)} · fechamento {closingStatus}</p><p className="text-sm">Próxima entrega interna: {internalDueDate}, horário de Brasília.</p><p className="text-sm">Próximos prazos oficiais confirmados: {official?.filter(d => d.due_at).length ? official.filter(d => d.due_at).map(d => `${d.title}: ${new Date(d.due_at!).toLocaleDateString('pt-BR')}`).join('; ') : 'Prazo oficial a confirmar'}</p></Card>
      <div className="grid gap-3 md:grid-cols-4">{[['Aprovado no mês', filteredExpenses?.filter(x => x.transaction.status === 'APROVADO').reduce((n, x) => n + Number(x.transaction.amount), 0) || 0], ['Pago no controle · mês', paidMonth], ['Conciliado · mês', reconciledMonth], ['A conciliar · mês', paidMonth - reconciledMonth]].map(([label, value]) => <div className="rounded-xl border bg-white p-4" key={label}><p className="text-xs text-gray-500">{label}</p><strong>{money(String(value))}</strong></div>)}</div>
      {tab === 'Financeiro' && <p className="text-xs text-gray-600">Fonte de cada despesa: parceria, recursos próprios ou outras fontes. Aprovado soma lançamentos aprovados; pago soma parcelas registradas; conciliado soma apenas parcelas vinculadas ao movimento do extrato. Totais desta faixa consideram despesas lançadas na competência filtrada.</p>}
      <div className="flex gap-2"><select className="input max-w-48" aria-label="Filtrar status" value={expenseStatus} onChange={e => setExpenseStatus(e.target.value)}>{['TODOS', 'PREPARACAO', 'LIBERADA'].map(s => <option key={s} value={s}>{human(s)}</option>)}</select><select className="input max-w-48" aria-label="Filtrar modalidade" value={expenseScope} onChange={e => setExpenseScope(e.target.value)}><option value="TODOS">Todas as modalidades</option><option value="GERAL">Geral do projeto</option>{[...new Set(expenses?.map(x => x.control?.scope).filter((x): x is string => Boolean(x)) || [])].map(s => <option key={s}>{s}</option>)}</select></div>
      {tab === 'Financeiro' && <div className="grid gap-2 md:grid-cols-3"><select className="input" value={fundingSource} onChange={e => setFundingSource(e.target.value)}><option value="PARCERIA">Recursos da parceria</option><option value="PROPRIOS">Recursos próprios</option><option value="OUTROS">Outras fontes</option></select><select className="input" value={expenseClass} onChange={e => setExpenseClass(e.target.value)}><option value="REVISAO">Classificação a revisar</option><option value="OBJETO">Execução do objeto</option><option value="LIMITE_25">Enquadramento no limite de 25%</option></select><input className="input" placeholder="Fundamento na atividade e rubrica aprovada" value={classBasis} onChange={e => setClassBasis(e.target.value)} /></div>}
      <div className="flex flex-wrap gap-2"><button disabled={busy} className="btn-secondary" onClick={() => mutate()}>Atualizar dados</button><button disabled={busy} className="btn-secondary" onClick={() => { mutate(); setTab('Visão geral') }}>Verificar pendências</button><button disabled={busy || !active} className="btn-secondary" onClick={() => setTab('Documentos')}>Gerar documentos</button><button disabled={busy || !active} className="btn-primary" onClick={() => action(() => api.post(`/accountability/monthly/${view.month.id}/close`, {}), 'Competência fechada com snapshot versionado.')}>Fechar competência</button><button className="btn-secondary" onClick={() => download(`/accountability/monthly/${view.month.id}/dossier.zip`, `dossie-${view.month.month.slice(0, 7)}.zip`)}>Exportar dossiê</button></div>
      <nav className="flex flex-wrap gap-2" aria-label="Seções da competência">{tabs.map(t => <button key={t} className={`rounded-lg px-3 py-2 text-sm ${tab === t ? 'bg-brand-700 text-white' : 'bg-white border'}`} onClick={() => setTab(t)}>{t}</button>)}</nav>
      {tab === 'Visão geral' && <Card title="O que falta para fechar este mês">{view.source_changed && <p className="text-sm text-amber-800">As fontes mudaram após o fechamento. A versão fechada foi preservada; abra revisão para atualizar o dossiê.</p>}{missing.length ? missing.map((m, i) => <div key={i} className="flex justify-between gap-3 border-b py-2 text-sm"><div><strong>{m.title}</strong><p className="text-gray-500">{m.why}</p></div><button className="text-brand-700" onClick={() => setTab(m.tab)}>Resolver</button></div>) : <p className="text-sm text-green-700">Nenhuma pendência crítica detectada. Revise o conteúdo e as exigências do instrumento antes de fechar.</p>}<p className="text-xs text-gray-500">A aprovação interna e o protocolo externo são etapas separadas.</p>{active && <button className="btn-secondary text-xs" disabled={busy} onClick={() => { const reason = window.prompt('Descreva por que não houve movimento nesta competência:'); if (reason) action(() => api.post(`/accountability/monthly/${view.month.id}/no-movement`, { reason }), 'Declaração sem movimento registrada para revisão.') }}>Declarar sem movimento</button>}</Card>}
      {tab === 'Documentos' && <Card title="Checklist e documentos"><p className="text-xs text-amber-800">Origem observada nos anexos não equivale a exigência confirmada. Confirme aplicabilidade e fonte no instrumento.</p>{view.month.requirements.map(r => <div key={r.id} className="border-b py-3 flex flex-wrap justify-between gap-3 text-sm"><div><strong>{r.rule.title}</strong><p className="text-xs text-gray-500">{human(r.rule.origin)} · {r.rule.source_reference ?? 'Fonte pendente'} · {r.applies ? 'aplicável' : 'aplicabilidade não confirmada'}</p><p className="text-xs">{r.evidence_ids.length} evidências · {r.rule.blocks_close ? 'bloqueia fechamento' : 'não bloqueia'}</p></div><select disabled={!active || busy} className="input max-w-56" value={r.status} onChange={e => action(() => api.patch(`/accountability/monthly/${view.month.id}/requirements/${r.id}`, { status: e.target.value }), 'Requisito atualizado.')}>{['PENDENTE', 'EM_PREPARACAO', 'AGUARDANDO_ASSINATURA', 'EM_REVISAO', 'VALIDADO', 'DISPENSADO'].map(s => <option key={s} value={s}>{human(s)}</option>)}</select></div>)}<div className="flex flex-wrap gap-2">{['PRESENCA', 'PONTO', 'SERVICOS', 'OBJETO', 'FINANCEIRO', 'CHECKLIST'].map(kind => <div key={kind} className="border rounded-lg p-2 text-sm"><strong>{human(kind)}</strong><div className="flex gap-1 mt-1"><button disabled={!active || busy || kind === 'PONTO'} className="btn-secondary text-xs" onClick={() => generate(kind, 'pdf')}>PDF</button><button disabled={!active || busy || kind === 'PONTO'} className="btn-secondary text-xs" onClick={() => generate(kind, 'xlsx')}>XLSX</button>{kind === 'FINANCEIRO' && <button disabled={!active || busy} className="btn-secondary text-xs" onClick={() => generate(kind, 'csv')}>CSV</button>}</div></div>)}</div>{view.month.documents.map(d => <div key={d.id} className="text-sm border-b py-2 flex flex-wrap items-center gap-2"><span>{d.kind} · {d.format.toUpperCase()} · v{d.version} · {human(d.signature_state)}</span><button className="text-brand-700" onClick={() => download(`/accountability/monthly/${view.month.id}/documents/${d.id}/file`, `${d.kind}-v${d.version}.${d.format}`)}>Baixar</button>{active && d.format === 'pdf' && <label className="text-brand-700 cursor-pointer">Anexar PDF assinado<input type="file" accept="application/pdf,.pdf" className="sr-only" onChange={e => { const file = e.target.files?.[0]; if (!file) return; const body = new FormData(); body.append('file', file); action(() => api.post(`/accountability/monthly/${view.month.id}/documents/${d.id}/signed-file`, body), 'Versão assinada anexada. Assinatura digital ainda não foi verificada criptograficamente.') }} /></label>}</div>)}</Card>}
      {tab === 'Execução física' && <Card title="Atividades e presença"><p className="text-xs text-gray-500">Aula Educa prevalece sobre registro por data. Sem chamada é pendente; aulas canceladas não entram no denominador.</p>{filteredAttendance?.length ? filteredAttendance.map(t => <div key={t.id} className="border-b py-3 text-sm"><strong>{t.nome} · {t.modalidade ?? 'modalidade pendente'}</strong><p>{t.aulas.length} aulas registradas · {t.beneficiarios.length} matrículas no período</p><div className="flex gap-2 my-2"><button disabled={!active || busy} className="btn-secondary text-xs" onClick={() => generate('PRESENCA', 'pdf', undefined, t.id)}>Lista PDF</button><button disabled={!active || busy} className="btn-secondary text-xs" onClick={() => generate('PRESENCA', 'xlsx', undefined, t.id)}>Lista XLSX</button></div>{t.aulas.map(a => <div key={a.id} className="flex gap-3 items-center text-xs py-1"><span>{a.inicio.slice(0, 10)}</span><select className="input max-w-40" disabled={!active || busy} value={a.status} onChange={e => action(() => api.patch(`/accountability/monthly/${view.month.id}/lessons/${a.id}/status`, { status: e.target.value }), 'Situação da aula atualizada.')}><option value="PREVISTA">Prevista</option><option value="REALIZADA">Realizada</option><option value="CANCELADA">Cancelada</option><option value="REMARCADA">Remarcada</option></select></div>)}{t.beneficiarios.map(b => <p key={b.matricula_id} className="text-xs text-gray-600">{b.nome}: {b.percent === null ? 'frequência pendente' : `${b.percent}%`} · {b.pending} registros pendentes</p>)}</div>) : <p>Nenhuma turma vinculada ao projeto.</p>}</Card>}
      {tab === 'Execução física' && <Card title="Equipe e ponto"><p className="text-xs text-gray-500">Escala planejada não gera marcação realizada. Registre entradas e saídas reais, inclusive múltiplos intervalos por dia.</p>{view.team.map(t => <div key={t.id} className="border-b py-2 text-sm flex justify-between"><span>{t.name} · {t.role}</span><span>{t.weekly_minutes ? `${t.weekly_minutes / 60}h/semana contratadas` : 'carga pendente'}</span></div>)}{active && <div className="grid gap-2 md:grid-cols-4"><input className="input" placeholder="Profissional" value={teamName} onChange={e => setTeamName(e.target.value)} /><input className="input" placeholder="Função" value={teamRole} onChange={e => setTeamRole(e.target.value)} /><input className="input" type="date" value={teamFrom} onChange={e => setTeamFrom(e.target.value)} /><button className="btn-secondary" disabled={busy || !teamName || !teamRole || !teamFrom} onClick={() => action(() => api.post(`/accountability/monthly/${view.month.id}/team`, { instrument_id: instrumentId, name: teamName, role: teamRole, valid_from: teamFrom }), 'Vínculo registrado. Confira contrato, carga e vigência.')}>Adicionar vínculo</button></div>}{view.team.length > 0 && active && <div className="grid gap-2 md:grid-cols-4"><select className="input" value={pointTeam} onChange={e => setPointTeam(e.target.value)}><option value="">Profissional</option>{view.team.map(t => <option key={t.id} value={t.id}>{t.name}</option>)}</select><input className="input" type="datetime-local" value={pointStart} onChange={e => setPointStart(e.target.value)} /><input className="input" type="datetime-local" value={pointEnd} onChange={e => setPointEnd(e.target.value)} /><button className="btn-secondary" disabled={busy || !pointTeam || !pointStart || !pointEnd} onClick={() => action(() => api.post(`/accountability/monthly/${view.month.id}/point`, { team_link_id: pointTeam, start_at: new Date(pointStart).toISOString(), end_at: new Date(pointEnd).toISOString(), kind: 'REALIZADO' }), 'Intervalo registrado.')}>Registrar intervalo</button></div>}{view.team.map(t => <button key={`${t.id}-pdf`} className="btn-secondary text-xs mr-2" disabled={!active || busy} onClick={() => generate('PONTO', 'pdf', t.id)}>Gerar ponto PDF · {t.name}</button>)}<p className="text-sm">Minutos registrados: {view.point.minutes}. {view.point.issues.join('; ')}</p></Card>}
      {tab === 'Financeiro' && <Card title="Execução financeira"><div className="grid gap-3 md:grid-cols-4 text-sm">{[['Entradas pagas', view.financial.received], ['Saídas pagas', view.financial.spent], ['Aprovadas, não pagas', view.financial.approved_unpaid], ['Saldo do período', view.financial.period_balance]].map(([k, v]) => <div key={k}><small className="block text-gray-500">{k}</small><strong>{money(v)}</strong></div>)}</div><p className="text-xs text-amber-800">{view.financial.reconciliation_message}</p>{view.financial.entries.map(e => <p className="text-sm border-b py-2" key={e.id}>{e.date.slice(0, 10)} · {e.description} · {human(e.status)} · {money(e.amount)}</p>)}</Card>}
      {tab === 'Resultados' && <Card title="Execução do objeto"><p className="text-sm">Atividades registradas: {view.attendance.reduce((n, t) => n + t.aulas.length, 0)}. Beneficiários únicos e atendimentos devem ser conferidos separadamente.</p><p className="text-sm text-amber-800">Comparação com metas indisponível até registrar metas aprovadas e fontes do plano de trabalho.</p><button disabled={!active || busy} className="btn-secondary" onClick={() => generate('OBJETO', 'pdf')}>Gerar prévia em PDF</button></Card>}
      {tab === 'Prestação oficial' && <Card title="Revisões e protocolo">{view.month.events.map(e => <p className="text-sm border-b py-2" key={e.id}>{new Date(e.created_at).toLocaleString('pt-BR')} · {human(e.action)} {e.reason && `· ${e.reason}`}</p>)}{view.month.status === 'FECHADA' && <button className="btn-secondary" disabled={busy} onClick={() => { const reason = window.prompt('Justificativa da nova revisão:'); if (reason) action(async () => { const { data } = await api.post(`/accountability/monthly/${view.month.id}/revisions`, { reason }); setSelectedId(data.id) }, 'Nova revisão aberta; a versão fechada foi preservada.') }}>Abrir revisão</button>}</Card>}
      {tab === 'Documentos' && active && <Card title="Confirmar exigência do instrumento"><p className="text-xs text-gray-500">Informe a cláusula, página ou orientação específica. A confirmação cria uma nova versão da regra.</p><div className="grid gap-2 md:grid-cols-3"><select className="input" value={ruleId} onChange={e => setRuleId(e.target.value)}><option value="">Requisito</option>{view.month.requirements.map(r => <option key={r.id} value={r.id}>{r.rule.title}</option>)}</select><input className="input" placeholder="Fonte no instrumento/plano" value={ruleSource} onChange={e => setRuleSource(e.target.value)} /><button className="btn-secondary" disabled={busy || !ruleId || !ruleSource} onClick={() => action(() => api.post(`/accountability/monthly/${view.month.id}/requirements/${ruleId}/confirm`, { source_reference: ruleSource, blocks_close: ruleBlocks }), 'Exigência confirmada e versionada.')}>Confirmar regra</button></div><label className="text-xs"><input type="checkbox" checked={ruleBlocks} onChange={e => setRuleBlocks(e.target.checked)} /> Bloqueia fechamento quando pendente</label></Card>}
      {tab === 'Documentos' && active && view.month.documents.some(d => d.signed_document_id) && <Card title="Vincular evidência assinada"><div className="grid gap-2 md:grid-cols-3"><select className="input" value={evidenceRule} onChange={e => setEvidenceRule(e.target.value)}><option value="">Requisito</option>{view.month.requirements.map(r => <option key={r.id} value={r.id}>{r.rule.title}</option>)}</select><select className="input" value={evidenceDoc} onChange={e => setEvidenceDoc(e.target.value)}><option value="">Documento assinado</option>{view.month.documents.filter(d => d.signed_document_id).map(d => <option key={d.id} value={d.signed_document_id}>{d.kind} · v{d.version}</option>)}</select><button className="btn-secondary" disabled={busy || !evidenceRule || !evidenceDoc} onClick={() => { const current = view.month.requirements.find(r => r.id === evidenceRule); if (current) action(() => api.patch(`/accountability/monthly/${view.month.id}/requirements/${evidenceRule}`, { status: 'EM_REVISAO', evidence_ids: [...new Set([...current.evidence_ids, evidenceDoc])] }), 'Evidência vinculada. Revisor deve validar o requisito.') }}>Vincular e enviar à revisão</button></div></Card>}
      {tab === 'Execução física' && active && view.team.length > 0 && <Card title="Planilhas de ponto editáveis">{view.team.map(t => <button key={t.id} className="btn-secondary text-xs mr-2" disabled={busy} onClick={() => generate('PONTO', 'xlsx', t.id)}>Gerar XLSX · {t.name}</button>)}</Card>}
      {tab === 'Resultados' && active && <Card title="Descrição confirmada da execução"><p className="text-xs text-gray-500">Descreva apenas fatos conferidos. A comparação com metas fica indisponível até cadastrar metas pactuadas.</p>{(['activities', 'results', 'deviations', 'justifications'] as const).map(key => <label key={key} className="block text-sm">{{ activities: 'Atividades realizadas', results: 'Resultados', deviations: 'Desvios', justifications: 'Justificativas' }[key]}<textarea className="input mt-1 min-h-20" value={execution[key]} onChange={e => setExecution({ ...execution, [key]: e.target.value })} /></label>)}<button className="btn-secondary" disabled={busy} onClick={() => action(() => api.patch(`/accountability/monthly/${view.month.id}/execution`, execution), 'Descrição da execução salva com histórico.')}>Salvar relato</button></Card>}
      {tab === 'Execução física' && <Card title="Resumo agregado da competência"><div className="grid gap-2 md:grid-cols-3 text-sm"><p>Matrículas: <strong>{view.attendance_summary?.enrollments ?? 0}</strong></p><p>Presenças em aulas: <strong>{view.attendance_summary?.presences ?? 0}</strong></p><p>Participantes únicos: <strong>{view.attendance_summary?.unique_participants ?? 0}</strong></p></div><p className="text-xs text-gray-600">Participantes únicos contam cada pessoa uma vez, mesmo em várias aulas ou modalidades.</p><select className="input max-w-64" value={executionScope} onChange={e => setExecutionScope(e.target.value)}><option value="TODAS">Todas as modalidades</option>{[...new Set(view.attendance.map(t => t.modalidade).filter((x): x is string => Boolean(x)))].map(s => <option key={s}>{s}</option>)}</select>{fixedProjectId && <a className="text-brand-700 text-sm" href={`?aba=chamada`}>Registrar aula e frequência no projeto</a>}</Card>}
      {tab === 'Execução física' && instrument && <Card title="Mídias das atividades"><p className="text-xs text-gray-600">Vincule um arquivo já cadastrado no projeto. Imagens identificáveis só aparecem a usuários autorizados; a divulgação exige autorização registrada no documento.</p>{media?.map(item => <div key={item.id} className="border-b py-2 text-sm">{human(item.kind)} · {new Date(item.recorded_on).toLocaleDateString('pt-BR')} · {item.scope} · {item.location} · {item.description} · {item.public_release ? 'Liberada para divulgação' : 'Restrita'} {!item.public_release && <button className="text-brand-700" onClick={() => action(() => api.post(`/accountability/monthly/media/${item.id}/release`), 'Mídia liberada após conferência da autorização.')}>Liberar</button>}</div>)}{active && <div className="grid gap-2 md:grid-cols-4"><input className="input" placeholder="ID do arquivo" value={mediaId} onChange={e => setMediaId(e.target.value)} /><select className="input" value={mediaKind} onChange={e => setMediaKind(e.target.value)}><option value="FOTO">Foto</option><option value="VIDEO">Vídeo</option></select><input className="input" type="date" value={mediaDate} onChange={e => setMediaDate(e.target.value)} /><input className="input" placeholder="Local" value={mediaPlace} onChange={e => setMediaPlace(e.target.value)} /><select className="input" value={mediaLesson} onChange={e => setMediaLesson(e.target.value)}><option value="">Atividade geral</option>{view.attendance.flatMap(t => t.aulas.map(a => <option key={a.id} value={a.id}>{t.nome} · {a.inicio.slice(0, 10)}</option>))}</select><input className="input" placeholder="Modalidade" value={mediaScope} onChange={e => setMediaScope(e.target.value)} /><input className="input" placeholder="Descrição" value={mediaDescription} onChange={e => setMediaDescription(e.target.value)} /><button className="btn-secondary" disabled={busy || !mediaId || !mediaDate || !mediaPlace || !mediaScope || !mediaDescription} onClick={() => action(() => api.post(`/accountability/monthly/instruments/${instrumentId}/media`, { document_id: mediaId, ...(mediaLesson && { lesson_id: mediaLesson }), kind: mediaKind, recorded_on: mediaDate, location: mediaPlace, scope: mediaScope, description: mediaDescription }), 'Mídia vinculada à execução física.')}>Vincular mídia</button></div>}</Card>}
      {tab === 'Resultados' && <Card title="Metas e indicadores do Plano de Trabalho"><p className="text-xs text-gray-600">Previsto e realizado para a competência selecionada. Sem dados permanece pendente. Matrículas, presenças e participantes únicos são medidas distintas.</p>{view.indicatorResults?.map(row => <p key={row.indicator.id} className="border-b py-2 text-sm"><strong>{row.indicator.name}</strong> · previsto {row.results[0]?.expected || row.indicator.target || 'a confirmar'} {row.indicator.unit || ''} · realizado {row.results[0]?.actual || 'sem dados'} · fonte {row.results[0]?.source || 'não informada'}</p>)}{active && <div className="grid gap-2 md:grid-cols-3"><select className="input" value={indicatorId} onChange={e => setIndicatorId(e.target.value)}><option value="">Selecione a meta</option>{view.indicatorResults?.map(row => <option key={row.indicator.id} value={row.indicator.id}>{row.indicator.name}</option>)}</select><input className="input" placeholder="Previsto" value={expected} onChange={e => setExpected(e.target.value)} /><input className="input" placeholder="Realizado" value={actual} onChange={e => setActual(e.target.value)} /><input className="input" placeholder="Método de apuração" value={method} onChange={e => setMethod(e.target.value)} /><input className="input" placeholder="Fonte dos dados" value={resultSource} onChange={e => setResultSource(e.target.value)} /><button className="btn-secondary" disabled={busy || !indicatorId || !expected || !method || !approvedPlan} onClick={() => action(() => api.post(`/accountability/monthly/${view.month.id}/results`, { indicator_id: indicatorId, work_plan_version: approvedPlan, expected, ...(actual && { actual }), method, source: resultSource, responsible_id: currentUser?.id || '' }), 'Resultado registrado com origem dos dados.')}>Registrar resultado</button></div>}</Card>}
      {tab === 'Visão geral' && active && <Card title="Avisos aos responsáveis"><p className="text-xs text-gray-600">Avise o gestor e os responsáveis pelos requisitos pendentes sobre a entrega interna. O sistema evita repetir o aviso da mesma competência.</p><button className="btn-secondary" disabled={busy} onClick={() => action(() => api.post(`/accountability/monthly/${view.month.id}/reminders`), 'Avisos enviados aos responsáveis cadastrados.')}>Avisar responsáveis</button></Card>}
      {tab === 'Documentos' && <Card title="Pastas do dossiê"><div className="grid gap-2 md:grid-cols-2">{['01 - Instrumento e Plano de Trabalho', '02 - Financeiro', '03 - Recursos Humanos', '04 - Execução das Atividades', '05 - Relatórios Mensais / Ano / Mês / Modalidade', '06 - Prestação de Contas', '07 - Transparência'].map(folder => <div key={folder} className="rounded-lg border p-3 text-sm">{folder}</div>)}</div><p className="text-xs text-gray-600">Arquivos assinados podem ser vinculados a múltiplos requisitos pela referência do documento.</p></Card>}
      {active && tab === 'Visão geral' && <Card title="Validações do fechamento interno"><p className="text-xs text-gray-600">As revisões financeira e de atividades podem ocorrer em paralelo. A devolução exige comentário. O documento assinado é um registro separado.</p><div className="grid gap-2 md:grid-cols-4">{['PROFESSOR', 'ATIVIDADES', 'FINANCEIRO', 'INSTITUCIONAL'].map(stage => { const latest = [...view.validations].reverse().find(v => v.stage === stage); return <div key={stage} className="rounded-lg border p-3 text-sm"><strong>{human(stage)}</strong><p>{latest ? human(latest.status) : 'Pendente'}</p><div className="mt-2 flex gap-1"><button className="btn-secondary text-xs" disabled={busy} onClick={() => action(() => api.post(`/accountability/monthly/${view.month.id}/validations`, { stage, status: 'APROVADO', role: stage }), 'Validação registrada com autor, papel e versão.')}>Validar</button><button className="btn-secondary text-xs" disabled={busy} onClick={() => { const comment = window.prompt('Motivo da devolução:'); if (comment) action(() => api.post(`/accountability/monthly/${view.month.id}/validations`, { stage, status: 'DEVOLVIDO', role: stage, comment }), 'Etapa devolvida para correção.') }}>Devolver</button></div></div> })}</div></Card>}
      {tab === 'Financeiro' && instrument && <Card title="Conferência de despesas e pagamentos"><p className="text-xs text-gray-600">Valores do mês filtrado. A operação bancária segue o procedimento oficial do instrumento.</p>{filteredExpenses?.map(({ transaction: t, control: c }) => <div key={t.id} className="border-b py-3 text-sm"><strong>{t.description} · {money(t.amount)}</strong><p>{human(t.status)} · {t.date.slice(0, 10)} · {c?.funding_source || 'Fonte a confirmar'} · {c?.release_status || 'Sem conferência'}</p><p>Pago no controle: {money(String(c?.payments.reduce((n, p) => n + Number(p.amount), 0) || 0))} · Saldo em aberto: {money(String(Number(t.amount) - (c?.payments.reduce((n, p) => n + Number(p.amount), 0) || 0)))}</p><div className="grid gap-2 md:grid-cols-4 mt-2"><input className="input" placeholder="Rubrica aprovada" value={budgetLine} onChange={e => setBudgetLine(e.target.value)} /><input className="input" placeholder="Versão do plano" value={planVersion} onChange={e => setPlanVersion(e.target.value)} /><input className="input" placeholder="Conta específica" value={account} onChange={e => setAccount(e.target.value)} /><button className="btn-secondary" disabled={busy} onClick={() => action(() => api.patch(`/accountability/monthly/instruments/${instrumentId}/expenses/${t.id}`, { budget_line: budgetLine, work_plan_version: planVersion, account_reference: account, funding_source: fundingSource, classification: expenseClass, classification_basis: classBasis }), 'Conferência salva. Classifique a natureza e valide os documentos exigidos antes da liberação.')}>Salvar conferência</button></div>{c && <div className="flex flex-wrap gap-1 mt-2">{['NOTA_FISCAL', 'CONTRATO', 'PESQUISA_PRECOS', 'COMPROVANTE_PAGAMENTO', 'EXTRATO', 'RECIBO_ENTREGA', 'FOLHA_ENCARGOS', 'RELATORIO_FORNECEDOR'].map(kind => <button key={kind} className="rounded border px-2 py-1 text-xs" onClick={() => editExpenseDocument(t.id, c, kind)}>{human(kind)}: {human(c.documents?.[kind]?.status || 'PENDENTE')}</button>)}</div>}{c && <div className="flex gap-2 mt-2"><button className="btn-secondary text-xs" disabled={busy} onClick={() => action(() => api.post(`/accountability/monthly/expenses/${c.id}/release`), 'Despesa liberada internamente.')}>Liberar internamente</button><button className="btn-secondary text-xs" disabled={busy} onClick={() => { const justification = window.prompt('Justificativa do pagamento fora do fluxo:'); if (justification) action(() => api.post(`/accountability/monthly/expenses/${c.id}/payments`, { amount: paymentAmount, paid_at: paymentDate, operation_reference: paymentReference, evidence_id: paymentEvidence, occurrence: true, justification }), 'Ocorrência registrada para conferência.') }}>Registrar ocorrência</button></div>}{c && <div className="grid gap-2 md:grid-cols-5 mt-2"><input className="input" placeholder="Valor pago" value={paymentAmount} onChange={e => setPaymentAmount(e.target.value)} /><input type="date" className="input" value={paymentDate} onChange={e => setPaymentDate(e.target.value)} /><input className="input" placeholder="Referência da operação" value={paymentReference} onChange={e => setPaymentReference(e.target.value)} /><input className="input" placeholder="ID do comprovante" value={paymentEvidence} onChange={e => setPaymentEvidence(e.target.value)} /><button className="btn-secondary" disabled={busy} onClick={() => action(() => api.post(`/accountability/monthly/expenses/${c.id}/payments`, { amount: paymentAmount, paid_at: paymentDate, operation_reference: paymentReference, evidence_id: paymentEvidence }), 'Pagamento registrado. Vincule ao extrato para conciliar.')}>Registrar pagamento</button></div>}{c?.payments.map(p => <p key={p.id} className="text-xs">Pagamento {money(p.amount)} · {p.statement_id ? 'Conciliado' : 'A conciliar'} · {p.occurrence ? 'Ocorrência' : 'Fluxo regular'} {!p.statement_id && <button className="text-brand-700" onClick={() => { const statement_id = window.prompt('ID do movimento do extrato:'); if (statement_id) action(() => api.post(`/accountability/monthly/payments/${p.id}/reconcile`, { statement_id }), 'Pagamento conciliado.') }}>Conciliar</button>}</p>)}</div>)}</Card>}
      {tab === 'Prestação oficial' && instrument && <Card title="Prestação oficial"><p className="text-sm">Prazo oficial a confirmar. O fechamento interno não envia a prestação.</p><a className="btn-secondary inline-block" href={typeof instrument.configuration?.official_url === 'string' ? instrument.configuration.official_url : 'https://portal.transferegov.sistema.gov.br/portal/home'} target="_blank" rel="noreferrer">Abrir no Transferegov</a><div className="grid gap-2 md:grid-cols-3"><input className="input" placeholder="Entrega" value={officialTitle} onChange={e => setOfficialTitle(e.target.value)} /><input className="input" placeholder="Exercício ou período" value={officialPeriod} onChange={e => setOfficialPeriod(e.target.value)} /><button className="btn-secondary" disabled={busy || !officialPeriod} onClick={() => action(() => api.post(`/accountability/monthly/instruments/${instrumentId}/official`, { title: officialTitle, period: officialPeriod }), 'Entrega oficial criada com prazo a confirmar.')}>Configurar entrega</button></div>{official?.map(d => <div key={d.id} className="border-b py-2 text-sm"><strong>{d.title} · {d.period}</strong><p>{human(d.status)} · {d.due_at ? new Date(d.due_at).toLocaleDateString('pt-BR') : 'Prazo oficial a confirmar'} · {d.protocol_number || 'Sem protocolo'}</p><div className="flex gap-2"><button className="text-brand-700" onClick={() => action(() => api.patch(`/accountability/monthly/official/${d.id}`, { status: 'PRONTO_PARA_ENVIO' }), 'Entrega pronta para envio oficial.')}>Pronto para envio</button><button className="text-brand-700" onClick={() => { const number = window.prompt('Número do protocolo:'); if (number && protocolDate && protocolEvidence) action(() => api.patch(`/accountability/monthly/official/${d.id}`, { status: 'PROTOCOLADO', protocol_number: number, protocol_at: new Date(`${protocolDate}T12:00:00Z`).toISOString(), protocol_evidence_id: protocolEvidence, package_version: view.month.revision }), 'Protocolo oficial registrado.') }}>Protocolar</button></div></div>)}<input className="input" type="date" aria-label="Data do protocolo" value={protocolDate} onChange={e => setProtocolDate(e.target.value)} /><input className="input" placeholder="ID do comprovante do protocolo" value={protocolEvidence} onChange={e => setProtocolEvidence(e.target.value)} /></Card>}
      {tab === 'Prestação oficial' && instrument && <Card title="Confirmar obrigações e prazos"><p className="text-xs text-gray-600">Informe o fundamento do termo assinado, plano aprovado ou norma aplicável. Sem confirmação, o prazo permanece a confirmar.</p><div className="grid gap-2 md:grid-cols-5"><input className="input" type="date" aria-label="Prazo oficial" value={officialDue} onChange={e => setOfficialDue(e.target.value)} /><input className="input" placeholder="Fundamento" value={officialBasis} onChange={e => setOfficialBasis(e.target.value)} /><input className="input" placeholder="ID do responsável" value={officialResponsible} onChange={e => setOfficialResponsible(e.target.value)} /><input className="input" placeholder="Documentos exigidos, separados por vírgula" value={officialDocs} onChange={e => setOfficialDocs(e.target.value)} /><button className="btn-secondary" disabled={busy || !officialPeriod || !officialDue || !officialBasis} onClick={() => action(() => api.post(`/accountability/monthly/instruments/${instrumentId}/official`, { title: officialTitle, period: officialPeriod, due_at: officialDue, legal_basis: officialBasis, responsible_id: officialResponsible || undefined, required_documents: officialDocs.split(',').map(x => x.trim()).filter(Boolean) }), 'Obrigação oficial confirmada com prazo e fundamento.')}>Salvar obrigação</button></div></Card>}
      {tab === 'Prestação oficial' && official?.some(d => d.status === 'PROTOCOLADO' || d.status === 'EM_DILIGENCIA') && <Card title="Diligências e decisão"><p className="text-xs text-gray-600">Registre cada prazo, resposta e protocolo no histórico da entrega.</p>{official.filter(d => d.status === 'PROTOCOLADO' || d.status === 'EM_DILIGENCIA').map(d => <div key={d.id} className="flex flex-wrap gap-2 border-b py-2 text-sm"><strong>{d.title} · {human(d.status)}</strong>{d.status === 'PROTOCOLADO' && <button className="btn-secondary text-xs" onClick={() => { const comment = window.prompt('Descrição da diligência:'); const diligence_due_at = window.prompt('Prazo da resposta (AAAA-MM-DD):'); if (comment && diligence_due_at) action(() => api.patch(`/accountability/monthly/official/${d.id}`, { status: 'EM_DILIGENCIA', comment, diligence_due_at }), 'Diligência registrada no histórico.') }}>Registrar diligência</button>}{d.status === 'EM_DILIGENCIA' && <button className="btn-secondary text-xs" onClick={() => { const number = window.prompt('Protocolo da resposta:'); if (number) action(() => api.patch(`/accountability/monthly/official/${d.id}`, { status: 'PROTOCOLADO', protocol_number: number, protocol_at: new Date().toISOString(), protocol_evidence_id: protocolEvidence, package_version: view.month.revision, comment: 'Resposta à diligência' }), 'Resposta à diligência registrada.') }}>Registrar resposta</button>}<button className="btn-secondary text-xs" onClick={() => { const decision_document_id = window.prompt('ID do documento da decisão:'); if (decision_document_id) action(() => api.patch(`/accountability/monthly/official/${d.id}`, { status: 'CONCLUIDO', decision_document_id }), 'Decisão oficial vinculada.') }}>Concluir com decisão</button></div>)}</Card>}
    </>}
  </div>
}
